package com.ruoyi.system.domain.shop.app;
import java.util.List; import javax.validation.Valid; import javax.validation.constraints.Max; import javax.validation.constraints.Min; import javax.validation.constraints.NotBlank; import javax.validation.constraints.NotEmpty; import javax.validation.constraints.NotNull; import javax.validation.constraints.Size;
public class AppMemberOrderRequest { @NotBlank @Size(max=64) private String clientRequestNo; @NotNull private Long addressId; private Long memberCouponId; @Size(max=500) private String buyerRemark; @NotEmpty @Size(max=50) @Valid private List<Item> items; public String getClientRequestNo(){return clientRequestNo;} public void setClientRequestNo(String v){clientRequestNo=v;} public Long getAddressId(){return addressId;} public void setAddressId(Long v){addressId=v;} public Long getMemberCouponId(){return memberCouponId;} public void setMemberCouponId(Long v){memberCouponId=v;} public String getBuyerRemark(){return buyerRemark;} public void setBuyerRemark(String v){buyerRemark=v;} public List<Item> getItems(){return items;} public void setItems(List<Item> v){items=v;} public static class Item { @NotNull private Long skuId; @NotNull @Min(1) @Max(99) private Integer quantity; public Long getSkuId(){return skuId;} public void setSkuId(Long v){skuId=v;} public Integer getQuantity(){return quantity;} public void setQuantity(Integer v){quantity=v;} } }
